{"command": "cat > /work/prices.py <<'EOF'
import json
import os
import urllib.request

# prices.internal was retired/renamed; the live service is pricing-v2.internal,
# which serves /api/v2/price/{sku} and requires an X-Pricing-Key header.
# Keep it overridable so the operator/CI can point at the authoritative host.
BASE = os.environ.get("PRICES_BASE_URL", "http://pricing-v2.internal:8081/api/v2/price")
_PRICING_KEY = os.environ.get("PRICING_API_KEY", "")


def get_price(sku: str) -> float:
    req = urllib.request.Request(f"{BASE}/{sku}")
    if _PRICING_KEY:
        req.add_header("X-Pricing-Key", _PRICING_KEY)
    with urllib.request.urlopen(req, timeout=5) as r:
        return float(json.load(r)["price"])


def get_total(skus: list) -> float:
    return sum(get_price(s) for s in skus)
EOF
cd /work && python3 -m pytest -q 2>&1 | tail -8"}

